import * as T from 'three';
import {PARTS} from './catalog.js';import {PLANET,radial} from './planet.js';
export const SUN_DIRECTION=new T.Vector3(12,24,12).normalize();
export function createCharge(parts){return new Map(parts.filter(p=>PARTS[p.type].battery).map(p=>[p.id,PARTS[p.type].battery]));}
export function powerTotals(parts,charge){return {stored:parts.reduce((s,p)=>s+(charge.get(p.id)||0),0),capacity:parts.reduce((s,p)=>s+(PARTS[p.type].battery||0),0)};}
export function inEclipse(pos){const r=radial(pos),along=r.dot(SUN_DIRECTION);return along<0&&r.lengthSq()-along*along<PLANET.radius**2;}
export function solarGeneration(parts,pos,q){if(inEclipse(pos))return 0;return parts.reduce((sum,p)=>{const rate=PARTS[p.type].solarPower||0;if(!rate)return sum;const normal=new T.Vector3(0,0,1).applyEuler(new T.Euler(...p.r)).applyQuaternion(q);return sum+rate*Math.max(0,normal.dot(SUN_DIRECTION));},0);}
export function powerStep(parts,charge,pos,q,commands,enabled,dt){const {stored,capacity}=powerTotals(parts,charge),generation=solarGeneration(parts,pos,q),reaction=enabled?parts.reduce((s,p)=>s+(p.reactionEnabled===false?0:PARTS[p.type].reactionTorque||0),0):0,demand=reaction/1000*Math.hypot(commands.pitch,commands.yaw,commands.roll),available=stored+generation*dt,consumed=Math.min(available,demand*dt),ratio=demand>0?Math.min(1,available/(demand*dt)):1,next=Math.max(0,Math.min(capacity,available-consumed)),change=next-stored;for(const p of parts){const cap=PARTS[p.type].battery||0;if(!cap)continue;const current=charge.get(p.id)||0,share=change>=0?(capacity>stored?(cap-current)/(capacity-stored):0):(stored?current/stored:0);charge.set(p.id,Math.max(0,Math.min(cap,current+change*share)));}return {stored:next,capacity,generation,demand,consumption:consumed/dt,ratio,eclipse:inEclipse(pos),net:change/dt};}
